// HT-41 T03 - Valida el aviso de despliegue y arma el ticket.
//
// Lo mandan deploy-lightsail-n8n.yml (despliegues) y ml-monitoring.yml
// (deriva del modelo, HT-49 T03) con la cabecera
// Authorization: Bearer <DEPLOY_WEBHOOK_SECRET>. El sobre es:
//   { eventType, projectKey, commitSha, repository, runId, message }
// y, para model_drift, ademas { modelName, modelVersion, psi }.
//
// Los IDs de tipo de solicitud son los del portal de Service Desk del equipo.
const TIPOS = {
  deployment_success: { requestTypeId: '19', etiqueta: 'Solicitud de cambio' },
  deployment_failure: { requestTypeId: '16', etiqueta: 'Fallo de la plataforma' },
  // La deriva es un incidente de la plataforma: va al mismo tipo de solicitud,
  // con su propia etiqueta en el resumen para distinguirla en el portal.
  model_drift: { requestTypeId: '16', etiqueta: 'Deriva del modelo' },
};

const body = $input.item.json.body || $input.item.json;
const falta = (v) => v === undefined || v === null || String(v).trim() === '';

let error = '';
if (falta(body.eventType) || !TIPOS[body.eventType]) {
  error = `"eventType" debe ser uno de: ${Object.keys(TIPOS).join(', ')}.`;
} else if (falta(body.projectKey)) {
  error = 'Falta "projectKey".';
} else if (falta(body.commitSha)) {
  error = 'Falta "commitSha".';
} else if (falta(body.repository)) {
  error = 'Falta "repository".';
} else if (falta(body.runId)) {
  error = 'Falta "runId".';
}

if (error) {
  return [{ json: { es_valido: false, http_code: 400, response_body: { error } } }];
}

const tipo = TIPOS[body.eventType];
const sha = String(body.commitSha);
const corto = sha.slice(0, 7);
const urlEjecucion = `https://github.com/${body.repository}/actions/runs/${body.runId}`;

// El runId va en el resumen a proposito: si el mismo despliegue reintenta el
// aviso, el ticket repetido se reconoce de un vistazo en el portal.
const esDeriva = body.eventType === 'model_drift';
const modelo = String(body.modelName || '').trim() || 'modelo';
const versionModelo = falta(body.modelVersion) ? '?' : String(body.modelVersion);
const resumen = esDeriva
  ? `[${tipo.etiqueta}] ${modelo} v${versionModelo} (run ${body.runId})`
  : `[${tipo.etiqueta}] ${body.repository} @ ${corto} (run ${body.runId})`;

const descripcion = [
  String(body.message || '').trim() || 'Sin mensaje.',
  '',
  ...(esDeriva ? [
    `Modelo: ${modelo}`,
    `Version: ${versionModelo}`,
    `PSI maximo: ${falta(body.psi) ? 'no disponible' : body.psi}`,
  ] : []),
  `Repositorio: ${body.repository}`,
  `Commit: ${sha}`,
  `Ejecucion: ${urlEjecucion}`,
].join('\n');

return [{
  json: {
    es_valido: true,
    http_code: 201,
    projectKey: String(body.projectKey),
    requestTypeId: tipo.requestTypeId,
    etiqueta: tipo.etiqueta,
    resumen,
    descripcion,
    url_ejecucion: urlEjecucion,
  },
}];

// HT-41 T03 - Busca el serviceDeskId del proyecto.
//
// La API del portal (/rest/servicedeskapi/request) pide el serviceDeskId
// numerico, que no es la clave del proyecto. Se resuelve una vez por llamada
// en vez de dejarlo escrito a mano: si alguien recrea el proyecto, el id
// cambia y esto sigue funcionando.
const clave = $('Validar aviso de despliegue').first().json.projectKey;
const valores = $input.first().json.values || [];
const encontrado = valores.find((sd) => sd.projectKey === clave);

if (!encontrado) {
  const claves = valores.map((sd) => sd.projectKey).join(', ') || 'ninguno';
  return [{
    json: {
      es_valido: false,
      http_code: 502,
      response_body: {
        error: `El proyecto "${clave}" no tiene portal de Service Desk. Portales visibles: ${claves}.`,
      },
    },
  }];
}

return [{ json: { es_valido: true, serviceDeskId: String(encontrado.id) } }];

// HT-41 T03 - Arma la solicitud con los campos que acepta su formulario.
//
// El formulario de "Solicitud de cambio" del portal UPTI no tiene el campo
// Descripcion, y Jira rechaza la solicitud entera si se lo manda (400 "El
// campo 'description' no es valido para este tipo de solicitud"). Si el
// formulario no lo tiene, o no se pudo leer, el detalle va como comentario
// interno de la solicitud ya creada.
const aviso = $('Validar aviso de despliegue').first().json;
const portal = $('Resolver portal del proyecto').first().json;
const campos = ($input.first().json.requestTypeFields || []).map((c) => c.fieldId);
const conDescripcion = campos.includes('description');

const requestFieldValues = { summary: aviso.resumen };
if (conDescripcion) requestFieldValues.description = aviso.descripcion;

return [{
  json: {
    cuerpo: { serviceDeskId: portal.serviceDeskId, requestTypeId: aviso.requestTypeId, requestFieldValues },
    comentario: conDescripcion ? '' : aviso.descripcion,
  },
}];

// HT-41 T03 - Respuesta final.
// Se lee del nodo que crea la solicitud: entre medio puede ir el comentario.
const creado = $('Crear solicitud en el portal').first().json || {};

if (creado.issueKey) {
  return [{
    json: {
      http_code: 201,
      response_body: {
        estado: 'creado',
        ticket: creado.issueKey,
        tipo: $('Validar aviso de despliegue').first().json.etiqueta,
        portal: creado._links && creado._links.web ? creado._links.web : null,
      },
    },
  }];
}

// Jira contesto algo que no es una solicitud creada: se devuelve tal cual para
// que quede en el log del despliegue y no haya que adivinar.
return [{
  json: {
    http_code: 502,
    response_body: {
      error: 'Jira no devolvio una solicitud creada.',
      detalle: creado.errorMessage || creado.errors || creado,
    },
  },
}];
